arguments.command:
python -c 'import csv,io,spglib,numpy as np; from pymatgen.core import Structure; rows=list(csv.DictReader(open("cdft_topo_pool.csv"))); print("id formula nat sg vol/atom density");
for r in rows:
 s=Structure.from_str(r["poscar"],fmt="poscar"); ds=spglib.get_symmetry_dataset((s.lattice.matrix,s.frac_coords,[x.specie.Z for x in s])); print(f"{r[chr(99)+chr(97)+chr(110)+chr(100)+chr(105)+chr(100)+chr(97)+chr(116)+chr(101)+chr(95)+chr(105)+chr(100)]} {r[chr(102)+chr(111)+chr(114)+chr(109)+chr(117)+chr(108)+chr(97)]:12} {len(s):3} {ds.international:10} {s.volume/len(s):7.2f} {s.density:6.2f}")'

python -c 'import csv; from pymatgen.core import Structure; from pymatgen.analysis.prototypes import AflowPrototypeMatcher; ids=set("c004 c005 c007 c010 c014 c015 c016 c017 c018 c021 c022 c028 c034 c036 c041 c045 c046 c048 c049 c050 c056 c057 c069 c070 c073 c076 c079 c086 c087 c088 c093 c097 c098 c099".split()); m=AflowPrototypeMatcher();
for r in csv.DictReader(open("cdft_topo_pool.csv")):
 if r["candidate_id"] in ids:
  s=Structure.from_str(r["poscar"],fmt="poscar"); x=m.get_prototypes(s); print(r["candidate_id"],r["formula"],[(p["tags"].get("mineral"),p["tags"].get("strukturbericht"),p["tags"].get("aflow")) for p in (x or [])])'

